type Tm = Omit<TermInput, "kind" | "asOf">;
const tm = (x: Tm): TermInput => ({ kind: "term", asOf, tags, ...x });

export const pancreaticCoreTerms: TermInput[] = [
  tm({ id: "nccn-resectability-criteria-pancreatic", name: "Resectability classes for pancreatic cancer (NCCN anatomical criteria and the 2017 international consensus)", category: "Clinical", wikipedia: W("Pancreatic_cancer"),
    aka: ["Anatomical resectability criteria", "180 degrees rule", "Vessel contact criteria", "Isaji criteria", "Anatomical, biological and conditional borderline resectability", "NCCN resectability classification"],
    tldr: "Surgeons class a pancreatic cancer as resectable, borderline resectable or locally advanced by how far it wraps around the arteries and veins behind the pancreas on the CT scan, measured in degrees of contact. Less than half way round an artery, or a vein the surgeon can rebuild, is borderline; more is locally advanced. A very high CA 19-9 or poor fitness can also make a tumour borderline.",
    summary: "The National Comprehensive Cancer Network adopted a definition of borderline resectable pancreatic cancer in 2006 and revised it yearly; the 2017 international consensus from the International Association of Pancreatology fixed three dimensions (Isaji 2018). Anatomical: tumour contact with the superior mesenteric artery or coeliac artery of less than 180 degrees without stenosis or deformity, contact with the common hepatic artery without involvement of the proper hepatic artery or coeliac artery, and contact with the superior mesenteric or portal vein including narrowing or occlusion that does not extend beyond the inferior border of the duodenum (so that reconstruction is possible). Biological: anatomically resectable disease with findings suspicious for, but unproven, distant or regional nodal metastases on PET-CT or biopsy, or a CA 19-9 above 500 U/mL. Conditional: anatomically and biologically resectable disease in a patient with performance status 2 or worse. Resectable disease has no arterial contact and venous contact of 180 degrees or less without contour irregularity; locally advanced (unresectable) disease has arterial encasement of more than 180 degrees or unreconstructable venous occlusion (NCCN; Tempero 2021). The classes are read off a pancreas protocol CT reported on the Society of Abdominal Radiology and American Pancreatic Association template, which asks the radiologist to state each vessel's degrees of contact (Al-Hawary 2014). In the UK the pancreatic multidisciplinary team applies them (NICE NG85 1.2.1). What follows from the class is on the parent page's treatment rows: surgery first for resectable disease (or neoadjuvant treatment in trials, NG85 1.8.2), chemotherapy first for borderline disease, and chemotherapy with or without radiotherapy or tumour treating fields for locally advanced disease, with re-imaging for conversion. A meta-analysis of seven randomised trials found neoadjuvant therapy improved survival in borderline resectable disease (hazard ratio 0.61) but not significantly in resectable disease (0.77) (van Dam 2022).",
    cancers: ["pancreatic", "resectable-pdac", "borderline-resectable-pdac", "locally-advanced-pdac"], terms: ["resectability", "pancreas-protocol-ct", "ca19-9", "neoadjuvant-versus-upfront-surgery-pancreatic", "vascular-resection-pancreatic"], technologies: ["ct", "pet-ct"],
    links: [SRC.isaji2018, SRC.tempero2021, SRC.nccn, SRC.alHawary2014, SRC.vanDam2022, SRC.ng85] }),

  tm({ id: "pancreas-protocol-ct", name: "Pancreas protocol CT (pancreatic protocol CT, dual-phase thin-slice CT with structured reporting)", category: "Diagnostics & imaging", wikipedia: W("CT_scan"),
    aka: ["Pancreatic protocol CT", "Pancreas protocol CT scan", "Dual-phase pancreatic CT", "Triple-phase pancreatic CT", "Pancreatic CT reporting template", "Structured CT report for pancreatic cancer"],
    tldr: "A pancreas protocol CT is a scan tuned for the pancreas: thin slices taken at two timed moments after contrast dye so that the tumour, the arteries and the veins all show up sharply. It is the first test NICE asks for when pancreatic cancer is suspected, before any stent is placed, and the report follows a template that lists every vessel the tumour touches and by how many degrees.",
    summary: "NICE NG85 asks for a pancreatic protocol CT before the bile duct is drained in people with obstructive jaundice and suspected pancreatic cancer (1.1.1), for people with pancreatic abnormalities without jaundice (1.1.4), as an option for cysts (1.1.7), and, covering chest, abdomen and pelvis, for every newly diagnosed patient who has not had one (1.3.1); a stent placed first causes inflammation and artefact that can obscure the tumour and its relation to the vessels. The scan acquires thin (about 1 mm) slices in a late arterial or pancreatic parenchymal phase, when the gland enhances brightly and a hypo-enhancing adenocarcinoma stands out and the arteries are opacified, and a portal venous phase for the veins and liver. The Society of Abdominal Radiology and the American Pancreatic Association published a consensus reporting template so that every report states the tumour's size and location, the degrees of contact with the superior mesenteric artery, coeliac axis and common hepatic artery, contact, narrowing or occlusion of the superior mesenteric and portal veins, variant arterial anatomy, and the presence of metastases, because incomplete free-text reports were a common reason for wrong resectability decisions (Al-Hawary 2014). Those measurements feed the resectability classes. When the diagnosis remains unclear NG85 adds FDG PET-CT and or endoscopic ultrasound with tissue sampling (1.1.2, 1.1.5), and for staging MRI of the liver, EUS for nodes and laparoscopy for small-volume peritoneal disease (1.3.3). Cancer Research UK notes that when the scan shows a removable tumour a biopsy is often not taken before surgery.",
    cancers: ["pancreatic", "resectable-pdac", "borderline-resectable-pdac", "ipmn-cystic-precursors"], terms: ["nccn-resectability-criteria-pancreatic", "obstructive-jaundice", "tnm-staging"], technologies: ["ct", "pet-ct", "endoscopic-ultrasound-systems"],
    links: [SRC.ng85, SRC.alHawary2014, SRC.crukTests] }),

  tm({ id: "distal-pancreatectomy", name: "Distal pancreatectomy (removal of the body and tail of the pancreas, usually with the spleen)", category: "Procedures", wikipedia: W("Pancreatectomy"),
    aka: ["Left pancreatectomy", "Distal pancreatectomy with splenectomy", "Spleen-preserving distal pancreatectomy", "Minimally invasive distal pancreatectomy", "Laparoscopic distal pancreatectomy", "Robotic distal pancreatectomy", "Radical antegrade modular pancreatosplenectomy", "RAMPS"],
    tldr: "Distal pancreatectomy removes the body and tail of the pancreas, the part to the left of the main vessels, usually with the spleen when the cause is cancer. The bile duct and duodenum are left alone, so there is no Whipple-type reconstruction; keyhole and robotic versions recover faster and, in a randomised trial, removed pancreatic cancer as completely as open surgery.",
    summary: "Tumours of the pancreatic body and tail present later than head tumours because they do not block the bile duct, so fewer are resectable; when they are, the operation is a distal pancreatectomy, with splenectomy and removal of the splenic vessels and regional nodes for cancer (the radical antegrade modular pancreatosplenectomy technique clears the nodes and the plane behind the gland), and spleen preservation for benign or low-grade tumours such as solid pseudopapillary neoplasm and small mucinous cystic neoplasms. The pancreatic stump is closed or stapled and the commonest complication is a pancreatic fistula; splenectomy carries a lifelong infection risk that vaccination and, in some centres, antibiotics address. Two randomised trials define the minimally invasive approach. LEOPARD (14 Dutch centres, 108 patients with left-sided tumours confined to the pancreas) found time to functional recovery of 4 days after minimally invasive against 6 days after open surgery, with less delayed gastric emptying and better quality of life at no extra cost, though the overall complication rate was unchanged (de Rooij 2019). DIPLOMA (35 centres in 12 countries, 258 patients with resectable pancreatic cancer, patients and pathologists blinded) found an R0 resection (1 mm or more) in 73 percent after minimally invasive and 69 percent after open distal pancreatectomy, within the non-inferiority margin, with comparable lymph node yield (Korrel 2023). NICE NG85 recommends standard rather than extended lymphadenectomy for head resections (1.8.4) and enzyme replacement before and after resection (1.6.2); after distal pancreatectomy diabetes and exocrine insufficiency depend on how much gland remains. Adjuvant chemotherapy follows as for any resected pancreatic ductal adenocarcinoma.",
    cancers: ["pancreatic", "resectable-pdac", "mcn-associated-carcinoma", "solid-pseudopapillary-neoplasm", "pancreatic-net"], terms: ["whipple", "resection-margins", "r0-r1-margin-pancreatic", "pancreatic-enzyme-replacement", "surgical-morbidity"], technologies: ["robotic-surgery"],
    links: [SRC.deRooij2019, SRC.korrel2023, SRC.ng85] }),

  tm({ id: "vascular-resection-pancreatic", name: "Vascular resection in pancreatic cancer surgery (portal and superior mesenteric vein resection; arterial resection)", category: "Procedures", wikipedia: W("Pancreaticoduodenectomy"),
    aka: ["Venous resection in pancreatectomy", "Portal vein resection", "Superior mesenteric vein resection and reconstruction", "Arterial resection in pancreatic surgery", "Appleby procedure", "Vascular reconstruction pancreatoduodenectomy"],
    tldr: "When a pancreatic cancer touches or narrows the big vein behind the pancreas, surgeons can cut out that segment of vein and rebuild it during the operation, which turns a borderline tumour into a removable one. Removing and rebuilding an artery is far riskier and is done only in selected patients in specialist centres, usually after chemotherapy has shrunk the tumour.",
    summary: "Venous involvement no longer rules out resection: the resectability criteria treat contact, narrowing or occlusion of the superior mesenteric or portal vein as borderline resectable provided the vein can be reconstructed, and the NCCN and international consensus define the limits by whether suitable vessel above and below remains for anastomosis (Isaji 2018). A meta-analysis of 27 studies and 9,005 patients (1,587 with portal or superior mesenteric vein resection) found venous resection associated with slightly higher postoperative mortality, a 9-point higher rate of R1 or R2 resection and worse survival than resection without it, which the authors attributed to more advanced disease in that group rather than to the technique (Giovinazzo 2016); in practice venous resection is routine in high-volume centres because the alternative is no resection. Arterial resection is different. In 26 retrospective studies (366 patients with arterial resection against 2,243 without) it carried about five times the perioperative mortality (odds ratio 5.04) and poor long-term outcome, and the authors concluded it may be justified only in highly selected patients, ideally within trials (Mollberg 2011). The distal pancreatectomy with coeliac axis resection (modified Appleby procedure) for body tumours encasing the coeliac axis, and arterial resections after neoadjuvant chemotherapy for locally advanced disease, are performed in specialist centres and reported as series. NICE NG85 asks that a specialist pancreatic multidisciplinary team makes these decisions (1.2.1). The resected vein or artery is examined by the pathologist, and true invasion of the vessel wall (rather than adherence to inflamed tissue) is one of the markers of a worse outlook.",
    cancers: ["pancreatic", "borderline-resectable-pdac", "locally-advanced-pdac", "resectable-pdac"], terms: ["nccn-resectability-criteria-pancreatic", "whipple", "resectability", "r0-r1-margin-pancreatic", "surgical-morbidity", "downstaging"], technologies: ["robotic-surgery"],
    links: [SRC.giovinazzo2016, SRC.mollberg2011, SRC.isaji2018, SRC.ng85] }),

  tm({ id: PERT_ID, name: "Pancreatic enzyme replacement therapy (PERT, pancreatin, Creon) for pancreatic exocrine insufficiency: why and how to take it", category: "Treatment jargon", wikipedia: W("Pancreatic_enzymes_(medication)"),
    aka: [...new Set(["PERT", "Pancreatin", "Creon", "Pancreatic enzyme supplements", "Enzyme capsules", "Pancreatic exocrine insufficiency", "PEI", "Steatorrhoea", "Malabsorption in pancreatic cancer", "Pancrelipase", "How to take PERT", ...(pertDraft?.aka ?? []).filter((a) => !/^(PERT|pancreatin|enzyme capsules|pancreatic exocrine insufficiency|Creon)$/i.test(a))])],
    tldr: "Most pancreatic cancers stop the gland's digestive enzymes reaching the gut, so fat passes through undigested and weight falls. Enzyme capsules taken with every meal and snack replace what is missing. NICE says everyone whose cancer cannot be removed should have them and that they should be considered before and after surgery, yet in UK records only about one patient in five was prescribed them.",
    summary: `Pancreatic exocrine insufficiency arises when the tumour blocks the main duct or the gland is removed or atrophied; the signs are pale, loose, oily stools that float and are hard to flush, bloating, wind and weight loss despite eating (Cancer Research UK symptoms page). Enteric-coated pancreatin (porcine lipase, amylase and protease in acid-resistant granules) is swallowed with the first mouthfuls of every meal and snack and titrated to symptoms and weight. NICE NG85 offers it to everyone with unresectable pancreatic cancer (1.6.1), asks clinicians to consider it before and after resection (1.6.2), recommends early enteral over parenteral nutrition after pancreatoduodenectomy (1.6.4) and advises against fish oils as a treatment for weight loss in unresectable disease (1.6.3); a note added in September 2024 records that supplies were disrupted and points prescribers to the Specialist Pharmacy Service tool for equivalent products. In the UK Clinical Practice Research Datalink, only 987 of 4,554 patients with pancreatic adenocarcinoma (21.7 percent) received enzyme replacement; in 807 propensity-matched pairs, adjusted median survival was 2.62 times longer in treated patients, a difference that held whether or not they had surgery or chemotherapy, although an observational study cannot exclude that fitter patients were more likely to be prescribed it (Roberts 2019). Weight loss in pancreatic cancer has three causes that overlap, poor intake, malabsorption and cachexia; 85 percent of patients meet the definition of cachexia, and a review from the Pancreatic Cancer Action Network recommends dietitian assessment, calorie and protein support, enzyme replacement, appetite stimulants where appropriate and exercise (Hendifar 2019). Diabetes after pancreatic surgery or from the tumour is managed alongside (the type 3c diabetes term).${pertDraft ? `\n\nHow to take it, from the living-with layer of this record. ${pertDraft.summary}` : ""}`,
    cancers: ["pancreatic", "locally-advanced-pdac", "metastatic-pdac", "resectable-pdac", "pancreatoblastoma"], terms: ["cachexia", "sarcopenia", "whipple", "distal-pancreatectomy", "obstructive-jaundice", "type-3c-diabetes-pancreatic-cancer", "eating-after-whipple", "nutrition-impact-symptoms"], technologies: ["oncology-nutrition", "nutrition-screening-mnt"],
    links: [SRC.ng85, SRC.roberts2019, SRC.hendifar2019, SRC.crukSymptoms, ...(pertDraft?.links ?? []).filter((l) => ![SRC.ng85.url, SRC.roberts2019.url].includes(l.url))] }),

  tm({ id: "lewis-negative", name: "Lewis-negative (Lewis antigen-negative, CA 19-9 non-secretor) status", category: "Biomarkers", wikipedia: W("CA19-9"),
    aka: ["Lewis antigen-negative", "Lewis negative phenotype", "CA 19-9 non-secretor", "FUT3 null", "Lewis blood group negative", "Le(a-b-)"],
    tldr: "About one person in ten to twenty cannot make the sugar that the CA 19-9 blood test measures, because they lack a working copy of the Lewis blood-group gene. In these Lewis-negative people the test stays low however large the cancer, so a normal CA 19-9 does not rule pancreatic cancer out, and their cancers appear to behave more aggressively.",
    summary: "CA 19-9 is the sialylated Lewis A antigen, made by an enzyme encoded by the FUT3 (Lewis) gene; people with two non-functional FUT3 alleles, about 5 to 10 percent of the population, cannot synthesise it, and the standard account is that their CA 19-9 is undetectable whatever the tumour burden (Ballehaninna 2012). That makes CA 19-9 falsely negative in this group, one of its main limitations alongside its low positive predictive value in screening and its rise in benign biliary obstruction and pancreatitis. A prospective series of 1,482 Chinese patients with pancreatic cancer genotyped FUT3 and found 8.4 percent Lewis-negative, but only 41.9 percent of them had CA 19-9 of 2 U/mL or less and 27.4 percent had a raised level above 37 U/mL, so the marker kept diagnostic value (area under the curve 0.842 against 0.898 in all patients); Lewis-negative status itself was an independent predictor of shorter survival (hazard ratio 1.30) (Luo 2018). A further analysis of 853 patients and cell lines found Lewis-negative cancers had a higher metastatic rate, lower CA 19-9 and higher MUC16 (CA 125) expression, and Lewis-negative cell lines grew and migrated faster, describing an aggressive subgroup (Int J Oncol 2020). Practical consequences: a normal CA 19-9 in a patient with a suspicious scan should not reassure; CA 125 or CEA is followed instead in known Lewis-negative patients; and trials that use CA 19-9 for eligibility or response exclude or mis-classify this group. The parent CA 19-9 term carries the marker's other uses.",
    cancers: ["pancreatic", "metastatic-pdac", "cholangiocarcinoma"], terms: ["ca19-9", "ppv"], technologies: ["liquid-biopsy"],
    links: [SRC.ballehaninna2012, SRC.luo2018, SRC.lewisNeg2020] }),

  tm({ id: "panin", name: "Pancreatic intraepithelial neoplasia (PanIN), the microscopic precursor of pancreatic cancer", category: "Pathology", wikipedia: W("Pancreatic_intraepithelial_neoplasia"),
    aka: ["PanIN", "PanIN-1", "PanIN-2", "PanIN-3", "Low-grade PanIN", "High-grade PanIN", "Pancreatic precursor lesion", "Carcinoma in situ of the pancreas", "Incipient IPMN"],
    tldr: "PanIN is the name for abnormal cells lining the small pancreatic ducts that can, over years, turn into pancreatic cancer. It is too small to see on any scan and is found only under the microscope, so it cannot be screened for directly. Pathologists now grade it as low or high grade, and high-grade PanIN was found in about one in twenty-five older people who died without pancreatic cancer.",
    summary: "In 2001 eight expert pathologists, shown 35 duct lesions, used more than 70 different terms for them; a working group then agreed the term pancreatic intraepithelial neoplasia with criteria for PanIN-1 (flat or papillary, minimal atypia), PanIN-2 (moderate atypia) and PanIN-3 (severe atypia, carcinoma in situ), and agreement improved when the cases were re-reviewed (Hruban 2001). The 2015 Baltimore consensus replaced the three grades with two, low grade (former PanIN-1 and 2) and high grade (former PanIN-3, carcinoma in situ), to align reporting with clinical consequences; it also concluded that PanIN of any grade at the resection margin of a pancreas removed for invasive cancer has no prognostic implication, set 0.5 to 1 cm as the size at which a lesion may be either a large PanIN or a small IPMN (calling those with intestinal or oncocytic papillae or GNAS mutations incipient IPMN), and asked that the distance between an IPMN and an invasive cancer be measured to distinguish associated from concomitant carcinoma (Basturk 2015). PanIN carries the same early genetic events as the cancer, KRAS mutation first, then CDKN2A loss, with TP53 and SMAD4 changes at high grade. How common it is: when 173 autopsy pancreata without cancer or IPMN (mean age 80.5) were examined in their entirety, PanIN-1 was present in 77 percent, PanIN-2 in 28 percent and PanIN-3 in 4 percent; high-grade lesions were always multifocal, commoner with diabetes and older age, sat more often in the body and tail and in small ducts, and 71 percent were accompanied by cystic change and lobular fibrosis, features that endoscopic ultrasound might detect (Matsuda 2017). Because PanIN is invisible to imaging, surveillance programmes aim instead at its consequences, cystic lesions and small cancers, and research looks for its signature in pancreatic juice and blood.",
    cancers: ["pancreatic", "ipmn-cystic-precursors", "ipmn-associated-carcinoma"], terms: ["pancreatic-cyst-high-risk-stigmata", "tumour-grade", "familial-pancreatic-cancer"], targets: ["kras", "cdkn2a", "tp53", "smad4"], technologies: ["pancreatic-surveillance", "histopathology-ihc"],
    links: [SRC.hruban2001, SRC.basturk2015, SRC.matsuda2017] }),

  tm({ id: "pancreatic-cyst-high-risk-stigmata", name: "High-risk stigmata and worrisome features of pancreatic cysts (IPMN and MCN surgical criteria)", category: "Diagnostics & imaging", wikipedia: W("Intraductal_papillary_mucinous_neoplasm"),
    aka: ["High-risk stigmata", "Worrisome features", "Mural nodule", "Main duct dilatation", "Enhancing solid component in a pancreatic cyst", "Fukuoka criteria", "Kyoto criteria", "Pancreatic cyst surveillance criteria"],
    tldr: "Most pancreatic cysts never become cancer, so doctors watch them and operate only when warning signs appear. The strongest signs, the high-risk stigmata, are jaundice from a cyst in the head of the pancreas, a solid lump inside the cyst that lights up with dye, or a main duct widened to a centimetre or more. Lesser signs, the worrisome features, prompt a closer look with endoscopic ultrasound.",
    summary: "NICE NG85 asks that people with pancreatic cysts have a pancreatic protocol CT or MRI with MRCP (1.1.7), the other test if more information is needed (1.1.8), and referral for resection with any of three high-risk features: obstructive jaundice with a cystic lesion in the head of the pancreas, an enhancing solid component in the cyst, or a main pancreatic duct of 10 mm diameter or larger (1.1.9); endoscopic ultrasound follows CT and MRI when the likelihood of malignancy or the need for surgery is unclear (1.1.10), with fine-needle aspiration and a CEA assay on the fluid alongside cytology when there is enough sample (1.1.11, 1.1.12). The international (Fukuoka 2012 and 2017, Kyoto 2024) guidelines cited on the cyst page use the same high-risk stigmata, with a threshold of an enhancing mural nodule of 5 mm or more and positive cytology, and a longer list of worrisome features: a cyst of 3 cm or more, a thickened or enhancing cyst wall, a main duct of 5 to 9 mm, a nodule under 5 mm, an abrupt change in duct calibre with distal atrophy, lymphadenopathy, a raised CA 19-9, rapid growth, pancreatitis and new-onset diabetes; worrisome features prompt EUS and shorter-interval surveillance rather than immediate surgery. The features are applied to intraductal papillary mucinous neoplasms and to mucinous cystic neoplasms; for MCNs the size (40 mm or more) and nodules predicted malignancy in the resected series (Crippa 2008; Yamao 2011). Two facts frame their use: cysts of 2 mm or more were found on MRCP in 49.1 percent of adults in a German population study, only 6 percent of them over 1 cm, and no cancer arose in five years (Kromrey 2018), so most cysts are trivial; and in the CAPS surveillance cohort 93 percent of the people who progressed to cancer or high-grade dysplasia had had detectable worrisome features first (Canto 2018), so the features work when applied to the right people. The Baltimore consensus (Basturk 2015) sets out the pathology grading behind the terms.",
    cancers: ["pancreatic", "ipmn-cystic-precursors", "ipmn-associated-carcinoma", "mcn-associated-carcinoma"], terms: ["panin", "obstructive-jaundice", "ca19-9", "pancreas-protocol-ct"], technologies: ["mri", "ct", "endoscopic-ultrasound-systems", "pancreatic-surveillance"],
    links: [SRC.ng85, SRC.kromrey2018, SRC.canto2018, SRC.basturk2015, SRC.crippa2008, SRC.yamao2011] }),

  tm({ id: "new-onset-diabetes-pancreatic-cancer", name: "New-onset diabetes as a signal of pancreatic cancer (and the ENDPAC score)", category: "Epidemiology & prevention", wikipedia: W("Pancreatic_cancer"),
    aka: ["New-onset diabetes and pancreatic cancer", "Pancreatic cancer-associated diabetes", "ENDPAC score", "END-PAC", "Enriching New-Onset Diabetes for Pancreatic Cancer", "Diabetes with weight loss"],
    tldr: "A pancreatic cancer can cause diabetes before any other symptom, so new diabetes after the age of 50, especially with weight loss rather than weight gain, is a recognised warning sign. About one in a hundred such people is found to have pancreatic cancer within three years; a simple score using weight change, blood sugar change and age picks out the smaller group who should have a scan.",
    summary: "The link runs both ways. Long-standing type 2 diabetes raises pancreatic cancer risk about 1.8- to 1.9-fold (Huxley 2005; Ben 2011), but the association is strongest in the first years after diabetes is diagnosed (odds ratio 2.1 for diabetes of under four years against 1.5 for five years or more, Huxley 2005), which is the tumour causing the diabetes rather than the reverse. In 512 newly diagnosed patients with pancreatic cancer, 47 percent had diabetes against 7 percent of age-matched controls, much of it new-onset, and it often resolved after the cancer was removed, so the tumour is diabetogenic (Pannala 2008); in a primary care cohort 47 percent of 111 patients had diabetes, 58 percent of it new-onset, and in 80 percent of those the diabetes began while the cancer was asymptomatic, a median of 6.5 months before diagnosis, while about a third of the new diabetes went undiagnosed (Aggarwal 2012). In 2,122 Rochester residents aged 50 or over who first met criteria for diabetes, 18 (0.85 percent, about 1 percent) were diagnosed with pancreatic cancer within three years, several times the expected rate (Chari 2005). One percent is too low to scan everyone, so the ENDPAC score (Enriching New-Onset Diabetes for Pancreatic Cancer) weights change in weight, change in blood glucose and age at onset: a score of 3 or more identified patients who developed cancer within three years with 80 percent sensitivity and specificity in the discovery cohort and 78 percent sensitivity and 85 percent specificity in validation, where cancer prevalence in the high-score group was 3.6 percent (Sharma 2018). NICE NG12 (1.2.5) lists new-onset diabetes with weight loss at 60 or over among the triggers for an urgent direct-access CT, and Cancer Research UK's symptoms page names new diabetes, or diabetes diagnosed within the previous year, as a sign. Cohort studies of new-onset diabetes with blood banking, and the ideas on this site that pair the signal with multi-cancer blood tests or continuous glucose monitoring, are trying to turn the window of about six months into earlier diagnoses. Living with the diabetes once the cancer is diagnosed (type 3c diabetes, its treatment and the diabetes team) is a separate glossary term.",
    cancers: ["pancreatic", "resectable-pdac", "ipmn-cystic-precursors"], terms: ["emergency-presentation", "ca19-9", "stage-shift", "ppv", "type-3c-diabetes-pancreatic-cancer"], technologies: ["mced", "pancreatic-surveillance"], drugs: ["galleri"], related: ["idea-mced-new-onset-diabetes", "idea-prev-new-onset-diabetes-pancreas-pathway"],
    links: [SRC.chari2005, SRC.pannala2008, SRC.aggarwal2012, SRC.sharma2018, SRC.huxley2005, SRC.ben2011, SRC.ng12, SRC.crukSymptoms] }),

  tm({ id: "r0-r1-margin-pancreatic", name: "R0 and R1 margins in pancreatic cancer: the 1 mm rule and standardised specimen reporting", category: "Pathology", wikipedia: W("Resection_margin"),
    aka: ["1 mm rule", "R1 within 1 mm", "R1 direct", "Royal College of Pathologists pancreatic margin", "Leeds protocol", "Axial slicing of pancreatoduodenectomy specimens", "Circumferential resection margin of the pancreas", "Posterior margin", "Superior mesenteric vein groove margin", "Superior mesenteric artery margin"],
    tldr: "After a pancreatic cancer is removed, the pathologist checks whether cancer reaches the cut edges of the specimen. In the UK, cancer within one millimetre of an edge counts as an incomplete (R1) resection even if it does not touch it. Reported this way most operations are R1, because the tumour creeps along nerves behind the gland; cancer touching the edge carries a worse outlook.",
    summary: "The general glossary term explains R0, R1 and R2; pancreatic cancer needs its own entry because the definition changed the numbers. The Royal College of Pathologists' pancreatoduodenectomy dataset defines R1 as microscopic tumour within 1 mm of a resection margin, and when a standardised protocol of multicolour inking of the margins, axial slicing and extensive sampling was introduced in Leeds, the R1 rate for pancreatic head cancer was 85 percent (22 of 26), involvement was often multifocal and most often posterior, and margin status correlated with survival (Verbeke 2006). In Heidelberg the R1 rate rose from 14 percent without a protocol to 76 percent with one, the medial (superior mesenteric vessel) margin being involved in 68 percent and the posterior in 47 percent, leading the authors to conclude that tumour growth pattern and thoroughness of examination, not surgical technique, determine R1 rates (Esposito 2008). In Liverpool 79 percent of 163 resections were R1 and 45 percent of those were equivocal (within 1 mm but not touching); their survival did not differ from unequivocal R1, supporting the 1 mm rule (Campbell 2009). Applying the strict definition to 561 pancreatoduodenectomies, 20.0 percent were R0 (1 mm or more), 21.9 percent R1 within 1 mm and 58.1 percent R1 direct, and margin status remained an independent determinant of survival even with adjuvant therapy in 85.9 percent, the authors calling for an international consensus because R0 and R1 rates are not comparable between series that use different definitions (Strobel 2017). In the ESPAC-3 adjuvant trial, 505 of 1,151 patients (43.9 percent) were R1; median survival was 24.9 months for R0 (more than 1 mm), 25.4 months for R1 within 1 mm, and direct margin involvement carried significantly worse overall and recurrence-free survival and more local recurrence (Ghaneh 2019). The margin that matters most is the medial or superior mesenteric artery margin, which is why neoadjuvant therapy (which shrinks the tumour away from the vessels) and vascular resection are judged partly by the R0 rate they achieve; the DIPLOMA trial used R0 of 1 mm or more as its primary endpoint (Korrel 2023). The R status is recorded alongside the TNM stage and node count and does not change the recommendation to give adjuvant chemotherapy.",
    cancers: ["pancreatic", "resectable-pdac", "borderline-resectable-pdac", "ipmn-associated-carcinoma"], terms: ["resection-margins", "whipple", "distal-pancreatectomy", "vascular-resection-pancreatic", "neoadjuvant-versus-upfront-surgery-pancreatic", "tnm-staging"], technologies: ["histopathology-ihc"],
    links: [SRC.verbeke2006, SRC.esposito2008, SRC.campbell2009, SRC.strobel2017, SRC.ghaneh2019, SRC.korrel2023] }),

  tm({ id: "neoadjuvant-versus-upfront-surgery-pancreatic", name: "Neoadjuvant therapy versus surgery first for resectable and borderline resectable pancreatic cancer", category: "Clinical", wikipedia: W("Neoadjuvant_therapy"),
    aka: ["Surgery-first versus chemotherapy-first in pancreatic cancer", "Perioperative chemotherapy pancreatic cancer", "Total neoadjuvant therapy for pancreatic cancer", "Preoperative chemotherapy pancreatic cancer", "PREOPANC question", "NORPACT question"],
    tldr: "For pancreatic cancers that look removable, doctors debate whether to operate at once and give chemotherapy afterwards, or to give chemotherapy first. Trials show chemotherapy first helps when the tumour is borderline, touching the big vessels, but it is not yet proven better for clearly removable tumours, where the largest trial found no gain and a US trial is still running.",
    summary: "The case for treatment first: micrometastatic disease is present in most patients, half never receive the planned adjuvant chemotherapy because of slow recovery or early relapse, response can be tested before a major operation, and shrinkage away from the vessels raises the R0 rate. The case for surgery first: the only cure is removed while it is still removable, and 10 to 20 percent progress during neoadjuvant treatment. The evidence. PREOPANC (16 Dutch centres, 246 patients with resectable or borderline resectable disease) randomised gemcitabine-based chemoradiotherapy before surgery against surgery first, both with adjuvant gemcitabine; the primary analysis missed, but at a median of 59 months overall survival favoured neoadjuvant treatment (hazard ratio 0.73) with a five-year survival of 20.5 percent against 6.5 percent, despite a median difference of only 1.4 months (Versteijne 2022). A meta-analysis of seven randomised trials (938 patients, all with gemcitabine-based neoadjuvant arms and none with adjuvant FOLFIRINOX) found neoadjuvant therapy improved survival overall (hazard ratio 0.66, median 19 to 29 months), significantly in borderline resectable disease (0.61) but not in resectable disease (0.77, not significant), with high certainty for the overall result (van Dam 2022). NORPACT-1, the Nordic trial of neoadjuvant FOLFIRINOX against surgery first with adjuvant chemotherapy in resectable head cancer, did not show a survival benefit (its paper is in this record's key papers); PREOPANC-2 found neoadjuvant FOLFIRINOX no better than neoadjuvant gemcitabine chemoradiotherapy (the PREOPANC trial record). Alliance A021806, a phase III trial of perioperative against adjuvant mFOLFIRINOX in resectable disease, has enrolled 358 patients, is active but no longer recruiting, has a primary completion date of December 2028 and had posted no results when this was written (design paper 2024; ClinicalTrials.gov NCT04340141). Guidance: NICE NG85 (2018) says neoadjuvant therapy for borderline resectable and for resectable disease should only be considered within a clinical trial (1.8.1, 1.8.2) and offers adjuvant gemcitabine plus capecitabine after resection (1.8.6); the NCCN guideline prefers neoadjuvant therapy for borderline resectable disease and allows it for resectable disease with high-risk features (a very high CA 19-9, a large tumour, suspicious nodes, severe symptoms). The RAS inhibitor idea linked from the parent record proposes testing the new drugs in this window.",
    cancers: ["pancreatic", "resectable-pdac", "borderline-resectable-pdac"], terms: ["neoadjuvant-adjuvant", "nccn-resectability-criteria-pancreatic", "r0-r1-margin-pancreatic", "resectability", "downstaging"], trials: ["preopanc", "norpact-1", "prodige-24"], drugs: ["folfirinox", "gemcitabine", "capecitabine"], technologies: ["cytotoxic-chemotherapy", "chemoradiation"], related: ["idea-ras-inhibitor-neoadjuvant-pdac"],
    links: [SRC.versteijne2022, SRC.vanDam2022, SRC.alliance2024, SRC.allianceCtg, SRC.ng85, SRC.nccn] }),

  tm({ id: "emergency-presentation", name: "Emergency presentation (route to diagnosis)", category: "Epidemiology & prevention", wikipedia: W("Emergency_department"),
    aka: ["Emergency route to diagnosis", "Emergency cancer diagnosis", "Diagnosed as an emergency", "Routes to diagnosis", "Emergency admission before cancer diagnosis", "Two week wait versus emergency presentation"],
    tldr: "An emergency presentation means a cancer was diagnosed after the person arrived as an emergency, through A&E or an urgent admission, rather than through a GP referral or screening. It is the route with the worst survival because the cancer is usually advanced by then. Almost half of pancreatic cancers in England are diagnosed this way, more than for almost any other common cancer.",
    summary: "England's Routes to Diagnosis work links hospital episode statistics, cancer waiting times, screening and registration data to assign every registered cancer to one of eight routes (screening, urgent suspected cancer referral, other GP referral, outpatient, inpatient elective, emergency presentation, death certificate only, unknown); the proportion by route differs sharply between cancers, and patients diagnosed through the emergency route have substantially lower one-year relative survival (Elliss-Brookes 2012). For pancreatic cancer in England in 2019, 22 percent of cases were diagnosed through an urgent suspected cancer (two week wait) referral and 45 percent through an emergency presentation (Cancer Research UK), against 4 percent emergency for breast cancer on the same source; the emergency share is highest for cancers whose early symptoms are vague or absent. A 2026 study built a digital measure of emergency presentation in the US Veterans Affairs system (positive predictive value 86.4 percent): 60.9 percent of 4,415 pancreatic cancer patients presented as emergencies, with 1.38 times the adjusted odds of advanced stage and 1.64 times the mortality, and nearly one in five emergency cases had a missed opportunity for earlier diagnosis on record review (Br J Cancer 2026). The SYMPTOM pancreatic study explains part of the problem: among 391 people referred with suspected pancreatic cancer, no first symptom distinguished the 30 percent who had cancer from those who did not, and only later symptoms such as jaundice did (Walter 2016). Reducing emergency presentation is an aim of the NHS Long Term Plan target for early-stage diagnosis; the levers are the NG12 referral rules, direct-access CT for GPs, awareness of new-onset diabetes and weight loss as signals, and rapid diagnostic centres for non-specific symptoms. The figure is worth knowing when reading survival statistics: a cancer with a 45 percent emergency share has its averages pulled down by the route as much as by the biology.",
    cancers: ["pancreatic", "metastatic-pdac", "cancer-of-unknown-primary"], terms: ["new-onset-diabetes-pancreatic-cancer", "stage-shift", "obstructive-jaundice"], technologies: ["ct"],
    links: [SRC.ellissBrookes2012, SRC.crukMain, SRC.emergency2026, SRC.walter2016, SRC.ng12] }),

  tm({ id: "familial-pancreatic-cancer", name: "Familial pancreatic cancer and inherited risk (who qualifies for surveillance)", category: "Genomics & genetics", wikipedia: W("Familial_pancreatic_cancer"),
    aka: ["Familial pancreatic cancer kindred", "FPC", "Hereditary pancreatic cancer", "Inherited pancreatic cancer risk", "Pancreatic cancer in the family", "Two first-degree relatives with pancreatic cancer", "High-risk individual for pancreatic cancer"],
    tldr: "Familial pancreatic cancer means at least two close relatives on the same side of the family have had the disease without a known gene fault to explain it. Members of such families have several times the usual risk, rising steeply with the number of relatives affected. With carriers of certain gene faults, they are the people offered yearly MRI or endoscopic ultrasound in surveillance programmes.",
    summary: "Definition and risk. A familial pancreatic cancer kindred has at least one pair of first-degree relatives with pancreatic cancer. In the Johns Hopkins National Familial Pancreas Tumor Registry (5,179 people from 838 kindreds), members of such kindreds with a first-degree relative affected had 9.0 times the expected incidence, rising to 6.4 times with two and 32 times with three affected first-degree relatives, while members of sporadic kindreds (1.8 times) and genetically unrelated spouses had no significant excess (Klein 2004); Cancer Research UK puts the risk from one first-degree relative at 62 to 76 percent higher. Genes explain a minority: 5.5 percent of 3,030 unselected patients carried a pathogenic variant in ATM, BRCA2, BRCA1, CDKN2A, TP53 or MLH1 (7.9 percent of those with a family history, 5.2 percent without) (Hu 2018), and most carriers have no family history (Shindo 2017); the syndromes with the highest relative risks are Peutz-Jeghers (more than 100 times), familial atypical multiple mole melanoma with CDKN2A (13 to 38 times) and hereditary pancreatitis with PRSS1 (more than 50 times) (Cancer Research UK). Who is offered surveillance. NICE NG85 offers it to hereditary pancreatitis with PRSS1, to BRCA1, BRCA2, PALB2 or CDKN2A carriers with one or more affected first-degree relatives, and to Peutz-Jeghers syndrome (1.1.15), and asks clinicians to consider it for two or more affected first-degree relatives across two generations and for Lynch syndrome with an affected first-degree relative (1.1.16), by MRI/MRCP or EUS (1.1.17). The International CAPS consortium (2020) starts familial surveillance at 50 or 55, or ten years before the youngest affected relative, uses EUS and MRI/MRCP yearly and added ATM carriers with one affected relative (Goggins 2020). What surveillance finds. In CAPS5, 77.8 percent of surveillance-detected cancers were stage I, and across CAPS1 to 5 five-year survival for screen-detected disease was 73.3 percent (Dbouk 2022); the Dutch programme found a 9.3 percent cumulative incidence in mutation carriers but none in mutation-negative familial kindreds over 63 months (Overbeek 2022); the Dutch CDKN2A cohort had a 20.7 percent cumulative incidence by age 70 with 83.3 percent of cancers resectable at imaging (Klatte 2022); the UK EUROPAC registry found one cancer and 41 cystic lesions in 321 people, the branch-duct IPMNs unrelated to inherited risk (Sheel 2019). The PRECEDE consortium is enrolling 20,000 people to standardise the approach (Gonda 2021; its trial record is linked). Practical route in the UK: ask the oncology team or GP for a clinical genetics referral; germline testing is offered to every patient with pancreatic cancer, and a positive result opens surveillance to relatives.",
    cancers: ["pancreatic", "brca-palb2-pdac", "ipmn-cystic-precursors"], terms: ["germline-vs-somatic", "gbrca-mutation", "pancreatic-cyst-high-risk-stigmata", "panin", "stage-shift"], targets: ["brca", "cdkn2a", "atm", "palb2", "stk11"], technologies: ["pancreatic-surveillance", "germline-testing", "mri", "endoscopic-ultrasound-systems"], trials: ["precede", "europac"], institutions: ["pancreatic-cancer-uk"], related: ["lynch-syndrome"],
    links: [SRC.klein2004, SRC.hu2018, SRC.shindo2017, SRC.ng85, SRC.goggins2020, SRC.dbouk2022, SRC.overbeek2022, SRC.klatte2022, SRC.sheel2019, SRC.gonda2021, SRC.crukRisk, SRC.crukScreening] }),
];

// The seven living-with drafts registered here, reviewed for sources and house style: the enzyme draft is folded into
// PERT_ID above, references to it are repointed, and the type 3c diabetes draft loses the "new-onset diabetes" alias,
// which belongs to the early-detection term new-onset-diabetes-pancreatic-cancer (the two terms link each other).
const livingTerms: TermInput[] = pancreaticLivingTermDrafts
  .filter((t) => t.id !== PERT_DRAFT_ID)
  .map((t) => ({
    ...t,
    tags: [...(t.tags ?? []), ...tags],
    aka: (t.aka ?? []).filter((a) => !/new-onset diabetes/i.test(a)),
    terms: [...new Set([...(t.terms ?? []).map((id) => (id === PERT_DRAFT_ID ? PERT_ID : id)), ...(t.id === "type-3c-diabetes-pancreatic-cancer" ? ["new-onset-diabetes-pancreatic-cancer"] : [])])],
  }));

const spike: Spike = {
  cancerId: "pancreatic",
  entities: [...pancreaticCoreSubtypes, ...pancreaticCoreTerms, ...livingTerms],
  patch: pancreaticPatch,
  supplements: [
    { id: "whipple", links: [SRC.whipple1935, SRC.ng85], terms: ["distal-pancreatectomy", "vascular-resection-pancreatic", "r0-r1-margin-pancreatic", "pancreatic-enzyme-replacement"], notes: [
      "The 1935 Annals of Surgery paper by Whipple, Parsons and Mullins described the two-stage operation for carcinoma of the ampulla of Vater; the one-stage pancreatoduodenectomy that bears his name followed.",
      "NICE NG85 (1.8.3, 1.8.4) asks surgeons to consider pylorus-preserving resection when the tumour can be adequately removed and standard rather than extended lymphadenectomy for head-of-pancreas cancer; enzyme replacement is considered before and after the operation (1.6.2) and early enteral nutrition is preferred to parenteral (1.6.4).",
    ] },
    { id: "ca19-9", links: [SRC.ballehaninna2012, SRC.luo2018, SRC.isaji2018], terms: ["lewis-negative", "nccn-resectability-criteria-pancreatic"], notes: [
      "In symptomatic patients CA 19-9 is 79 to 81 percent sensitive and 82 to 90 percent specific; as a screening test its positive predictive value is 0.5 to 0.9 percent; a level above 100 U/mL suggests unresectable or metastatic disease, and a fall of 20 to 50 percent or normalisation after surgery or chemotherapy predicts longer survival (Ballehaninna 2012).",
      "A CA 19-9 above 500 U/mL makes an anatomically resectable tumour biologically borderline resectable in the 2017 international consensus (Isaji 2018). Not every Lewis-negative patient is a non-secretor: 27.4 percent of Lewis-negative patients in a 1,482-patient series still had a raised level (Luo 2018).",
    ] },
    { id: "cachexia", cancers: ["pancreatic"], links: [SRC.hendifar2019, SRC.bachmann2008, SRC.impact2019], terms: ["pancreatic-enzyme-replacement"], notes: [
      "Pancreatic cancer is the archetype: 85 percent of patients meet the classic definition of cancer cachexia (Hendifar 2019); 40.5 percent of 227 patients scheduled for resection were already cachectic, and their resection rate was 48.9 against 77.8 percent because metastases were found more often (Bachmann 2008); 73 percent of 94 advanced patients were sarcopenic at baseline and 21 percent lost 10 percent or more of skeletal muscle by the first restaging scan (IMPACT study 2019).",
      "Malabsorption from exocrine insufficiency adds to cachexia in this cancer, so pancreatic enzyme replacement is part of the treatment (NICE NG85 1.6); fish oils are not recommended for weight loss in unresectable disease (1.6.3).",
    ] },
    { id: "resection-margins", links: [SRC.campbell2009, SRC.ghaneh2019], terms: ["r0-r1-margin-pancreatic"], notes: [
      "Pancreatic cancer uses a 1 mm rule: tumour within 1 mm of a margin is R1 (Royal College of Pathologists), which makes 76 to 85 percent of standardised head resections R1; the pancreatic glossary term carries the series and the ESPAC-3 survival by margin (Ghaneh 2019).",
    ] },
    { id: "resectability", links: [SRC.isaji2018, SRC.tempero2021], terms: ["nccn-resectability-criteria-pancreatic", "vascular-resection-pancreatic", "neoadjuvant-versus-upfront-surgery-pancreatic"], notes: [
      "For pancreatic cancer the classes are defined in degrees of vessel contact on a pancreas protocol CT, with biological (CA 19-9 above 500 U/mL, suspected spread) and conditional (performance status) dimensions added by the 2017 international consensus (Isaji 2018); the pancreatic glossary term sets them out.",
    ] },
  ],
};
export default spike;
